import{M as l}from"./chunks/MicroarchDiagram.LGXjWy-x.js";import{o as s,c as i,a2 as r,j as e,E as t,a as o}from"./chunks/framework.CNQbXYGB.js";const n={class:"details custom-block"},d={class:"details custom-block"},c={class:"details custom-block"},b=JSON.parse('{"title":"1.5 · 三分钟白板复述","description":"","frontmatter":{},"headers":[],"relativePath":"01-overview/whiteboard-review.md","filePath":"01-overview/whiteboard-review.md"}'),m={name:"01-overview/whiteboard-review.md"},v=Object.assign(m,{setup(h){return(u,a)=>(s(),i("div",null,[a[6]||(a[6]=r('<h1 id="_1-5-·-三分钟白板复述" tabindex="-1">1.5 · 三分钟白板复述 <a class="header-anchor" href="#_1-5-·-三分钟白板复述" aria-label="Permalink to &quot;1.5 · 三分钟白板复述&quot;">​</a></h1><p>合上前四章，从 <code>C[i] = A[i] + B[i]</code> 开始。用三分钟画三张图，依次回答<strong>任务怎么分、数据怎么走、等待怎么藏</strong>。可以先讲一遍，再展开参考。</p><h2 id="任务怎么分" tabindex="-1">任务怎么分 <a class="header-anchor" href="#任务怎么分" aria-label="Permalink to &quot;任务怎么分&quot;">​</a></h2><p>用 <code>N=1000</code>、<code>blockDim=256</code>、BW100 Wave64 的例子。画出软件里的 Grid 和 Block，把一个 Block 展开成 wave，再画出承载它们的 CU。说出最后一个 wave 的有效线程数。</p>',4)),e("details",n,[a[0]||(a[0]=e("summary",null,"查看参考图与讲法",-1)),t(l,{kind:"mapping"}),a[1]||(a[1]=e("p",null,[o("一次 launch 提交 4 个 Block，每个 Block 256 个线程。BW100 上每个 Block 有 4 个 wave，一个 Block 的 wave 在分配到的同一个 CU 上执行。同一个 CU 可以驻留多个 Block。最后一个 wave 的全局索引是 960–1023，40 个线程对应有效元素。"),e("a",{href:"./software-stack.html"},"回到 1.1")],-1))]),a[7]||(a[7]=e("h2",{id:"数据怎么走",tabindex:"-1"},[o("数据怎么走 "),e("a",{class:"header-anchor",href:"#数据怎么走","aria-label":'Permalink to "数据怎么走"'},"​")],-1)),a[8]||(a[8]=e("p",null,"在一个有效 lane 上，从 A、B 的地址画到 C 的写回。标出操作数进入哪类寄存器、在哪里计算、何时需要等待。再说一种需要 LDS 的场景。",-1)),e("details",d,[a[2]||(a[2]=e("summary",null,"查看参考图与讲法",-1)),t(l,{kind:"memory"}),a[3]||(a[3]=e("p",null,[o("向量加法对全局地址发加载，结果进入 VGPR，由 VALU 做逐 lane 加法，最后写回 C。访问可能命中缓存。示例 ISA 用 "),e("code",null,"s_waitcnt vmcnt(0)"),o(" 确保相关操作满足依赖，才使用加载结果。分块协作时，线程可以先把数据写进 LDS，再以 Block 屏障协调消费者。"),e("a",{href:"./../02-compute/cu-and-simt.html"},"回到 1.2"),o(" · "),e("a",{href:"./../03-memory/memory-hierarchy.html"},"回到 1.3")],-1))]),a[9]||(a[9]=e("h2",{id:"等待怎么藏",tabindex:"-1"},[o("等待怎么藏 "),e("a",{class:"header-anchor",href:"#等待怎么藏","aria-label":'Permalink to "等待怎么藏"'},"​")],-1)),a[10]||(a[10]=e("p",null,"画出 Wave A 发出加载和使用结果之间的间隔。说出同一个 wave 和其他 wave 分别可以做什么，再解释为什么仅靠驻留数量算不出速度。",-1)),e("details",c,[a[4]||(a[4]=e("summary",null,"查看参考图与讲法",-1)),t(l,{kind:"latency"}),a[5]||(a[5]=e("p",null,[o("有其他就绪 wave 时，调度器可以选择它发射，这是线程级并行提供的机会。同一 wave 有与加载结果无关的指令时，可以先发出独立工作，这是指令级并行提供的机会。驻留上限由资源决定，真实耗时还取决于指令依赖、数据路径和可用发射资源。"),e("a",{href:"./../04-scheduling/occupancy-and-roofline.html"},"回到 1.4")],-1))]),a[11]||(a[11]=r('<h2 id="换一道题还能讲出来吗" tabindex="-1">换一道题还能讲出来吗？ <a class="header-anchor" href="#换一道题还能讲出来吗" aria-label="Permalink to &quot;换一道题还能讲出来吗？&quot;">​</a></h2><h3 id="改启动参数" tabindex="-1">改启动参数 <a class="header-anchor" href="#改启动参数" aria-label="Permalink to &quot;改启动参数&quot;">​</a></h3><p>仍处理 1000 个元素。把 Block 改成 128 个线程，Grid 有多少个 Block？最后一个 Block 和最后一个 wave 分别有多少有效线程？</p><details class="details custom-block"><summary>查看答案</summary><p>Grid 有 <strong>8 个 Block</strong>，每个 Block 有 <strong>2 个 wave</strong>。最后一个 Block 从索引 896 开始，有 <strong>104 个有效线程</strong>；最后一个 wave 从 960 开始，仍然是 <strong>40 个有效线程</strong>。这些是由 launch 参数和 Wave64 算出的逻辑数量，执行顺序由设备决定。</p></details><h3 id="换同步场景" tabindex="-1">换同步场景 <a class="header-anchor" href="#换同步场景" aria-label="Permalink to &quot;换同步场景&quot;">​</a></h3><p>线程 A 把数据写进 LDS，同一个 Block 的线程 B 接下来要读。A 等到自己的写操作完成，B 就一定能读吗？Host 在哪一层等待？</p><details class="details custom-block"><summary>查看答案</summary><p>B 还需要与 A 在 Block 范围按约定协调，保证写入与读取的顺序并满足可见性。本例用 <code>__syncthreads()</code>。<code>s_waitcnt</code> 针对执行该指令的 wave 等待指定类别的未完成操作。Host 用相关 stream 或设备同步观察提交的工作何时完成。</p></details><h3 id="用证据解释反例" tabindex="-1">用证据解释反例 <a class="header-anchor" href="#用证据解释反例" aria-label="Permalink to &quot;用证据解释反例&quot;">​</a></h3><p>E04 在 4 wave/CU 上限时 8 条链最快，在 32 wave/CU 上限时 2 条链最快。这个结果能支持什么结论？还不能把原因归给哪个指标？</p><details class="details custom-block"><summary>查看答案</summary><p>数据支持<strong>独立加载链的收益取决于驻留条件</strong>。E04 固定每线程的逻辑读取量，也观察到链数变化伴随循环次数、发射顺序和 VGPR 变化。驻留上限是 HIP API 的估计；现有实验没有隔离哪一个因素导致 32 wave/CU 下 8 条链更慢。把预测、观测和机制假设分开说。<a href="./../labs/lab04-occupancy-ilp.html">查看 E04 原始证据</a></p></details><h2 id="脱稿检查" tabindex="-1">脱稿检查 <a class="header-anchor" href="#脱稿检查" aria-label="Permalink to &quot;脱稿检查&quot;">​</a></h2><ul><li>能把 <strong>Grid、Block、wave、lane、CU</strong> 放到各自的位置，并算对尾部有效线程。</li><li>能说出 <strong>SALU、VALU、MMAC</strong> 分别处理哪类工作，指出向量加法走哪条路径。</li><li>能在图上区分 <strong>寄存器、LDS、Cache、HBM</strong>，再说明 <code>s_waitcnt</code>、Block 屏障和 Host 同步各自在等谁。</li><li>能用 <strong>E04</strong> 解释驻留与独立工作的关系，说出一个已经观测到的结果和一个仍待验证的机制。</li></ul><p>编程模型与同步语义可查 DTK 26.04《HIP C++ 编程指南》《HIP Runtime API 开发手册》。BW100 对照值和具体指令来自 <a href="./../baselines/bw100-gfx936.html">实测档案</a>；z100 结构仅作为 <a href="./software-stack.html#_1-2-dcu-的物理硬件组织" target="_self">架构参考</a>。</p><p><a href="./../profiling/01-toolchain-overview.html">继续 · Profiling 工具与 ISA</a> · <a href="./../labs/">回到实验索引</a></p>',14))]))}});export{b as __pageData,v as default};
